package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.asof.AsOfStore;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class ApplySheetToday {
    public void apply(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by,
            @Val LocalDate today, SheetRepository repository, ClaimRepository claims, AsOfStore asOf, Out<Sheet> sheet) {
        String id = sheetId.trim();
        Sheet was = repository.find(id);
        if (was != null && !today.equals(LocalDate.parse(was.today()))) {
            // what the sheet holds now is what it holds as of every date up to its old today
            asOf.snapshot(id, LocalDate.parse(was.today()), today);
        }
        repository.open(id, by == null ? "" : by);
        if (!today.equals(repository.today(id))) {
            claims.unlockAll(id); // a new today closes every open claim editor
        }
        repository.setToday(id, today);
        sheet.set(repository.find(id));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSheetToday {
    public void validate(@RequestBody SheetTodayRequest request, Out<LocalDate> today)
            throws InvalidSheetTodayException {
        String value = request == null || request.today() == null ? "" : request.today().trim();
        try {
            today.set(LocalDate.parse(value));
        } catch (DateTimeParseException e) {
            throw new InvalidSheetTodayException("Not a date: " + value);
        }
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.Comparator;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** After the sheet's today is set: with grace days set, closes every open period (not closed or soft-closed: a soft-closed one is closed only by hand) whose to-date plus
 *  the grace days is before the new today, in order of their to-dates, as a close by hand does, each
 *  recorded as PERIOD_CLOSED with auto=yes. */
public class AutoClosePeriods {
    public void close(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by, PeriodRepository periods,
            ClaimRepository claims, ClaimLogRepository log, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets, Audit audit) {
        String id = sheetId.trim();
        String user = by == null ? "" : by;
        String grace = settings.find(id, SettingRepository.GRACE_DAYS);
        if (grace == null) return;
        LocalDate today = sheets.today(id);
        int days = Integer.parseInt(grace);
        for (Period found : periods.list(id).stream().sorted(Comparator.comparing(Period::to)).toList()) {
            if (found.fixed() || !LocalDate.parse(found.to()).plusDays(days).isBefore(today)) continue;
            Period closed = PeriodClosing.closeNow(found, user, periods, claims, log, people, rates, settings, sheets);
            audit.record("PERIOD_CLOSED sheet=" + id + " by=" + user + " period=" + closed.name()
                    + " total=" + closed.closedTotal() + " auto=yes");
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a close that went through is recorded. */
public class RecordPeriodClosed {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Period period, Audit audit) {
        audit.record("PERIOD_CLOSED sheet=" + period.sheetId() + " by=" + (by == null ? "" : by)
                + " period=" + period.name() + " total=" + period.closedTotal());
    }
}
-- What a sheet held each time its today changed: the sheet's rows are copied into their own schema
-- (SNAP_<id>), kept with the today they stood at (today_was) and the today set next (today_now). A
-- screen shown as of a date reads the last copy taken as the sheet's today moved past that date.
CREATE SEQUENCE sheet_snapshot_seq;
CREATE TABLE sheet_snapshot (
    id        BIGINT       PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    today_was DATE         NOT NULL,
    today_now DATE         NOT NULL
);
CREATE INDEX sheet_snapshot_sheet ON sheet_snapshot (sheet_id, id);

